def shortest_path(edges, start, end):
    """
    Find the shortest path from start to end using Dijkstra's algorithm.

    Args:
        edges: List of tuples (from_node, to_node, weight) representing directed weighted edges
        start: Starting node (string or hashable)
        end: Ending node (string or hashable)

    Returns:
        Tuple (distance, path) where distance is the total weight and path is a list of nodes.
        Returns (None, None) if no path exists.
        Raises ValueError if any edge has a negative weight.

    Raises:
        ValueError: If an edge has a negative weight.
    """
    # Case: Same start and end node
    if start == end:
        return (0, [start])

    # Validate for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative weights are not allowed.")

    # Build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    import heapq

    # Dijkstra's algorithm setup
    distances = {start: 0}
    previous = {}
    pq = [(0, start)]
    visited = set()

    while pq:
        dist, node = heapq.heappop(pq)

        if dist > distances.get(node, float('inf')):
            continue

        # Check if end reached
        if node == end:
            path = []
            curr = end
            while curr is not None:
                path.append(curr)
                curr = previous.pop(curr)
            return (dist, path[::-1])  # Reverse path since we backtracked

        visited.add(node)

        for neighbor, weight in graph.get(node, []):
            new_dist = dist + weight
            if neighbor not in visited:
                if neighbor not in distances or new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    previous[neighbor] = node
                    heapq.heappush(pq, (new_dist, neighbor))

    # No path found
    return (None, None)
